fn choose(indices: Vec<u8>, choices: Vec<Vec<f64>>) -> Vec<f64> {
    // The length of the output vector equals the length of the indices array.
    let len = indices.len();
    let mut result = Vec::with_capacity(len);

    for i in 0..len {
        // Convert the index (u8) to usize for indexing into choices
        let row = indices[i] as usize;
        // The column is `i`
        result.push(choices[row][i]);
    }

    result
}